ll n,m,a[100005],sum[400005],delA[400005],delM[400005];
void pushdown(int k,int l,int r)
{
	if(l==r || delA[k]==0&&delM[k]==1)	return;
	int mid=(l+r)/2;
	delA[k*2]=(delA[k*2]*delM[k]%mo+delA[k]%mo)%mo;
	delA[k*2+1]=(delA[k*2+1]*delM[k]%mo+delA[k]%mo)%mo;
	delM[k*2]=delM[k*2]*delM[k]%mo;
	delM[k*2+1]*=delM[k*2+1]*delM[k]%mo;
	sum[k*2]=(sum[k*2]*delM[k]%mo+(mid-l+1)*delA[k]%mo)%mo;
	sum[k*2+1]=(sum[k*2+1]*delM[k]%mo+(r-mid)*delA[k]%mo)%mo;
	delA[k]=0;
	delM[k]=1;
}
void build(int k,int l,int r)
{
	if(l==r)
	{
		sum[k]=a[l];
		return;
	}
	int mid = (l+r)/2;
	build(k*2,l,mid);
	build(k*2+1,mid+1,r);
	sum[k]=(sum[k*2]+sum[k*2+1])%mo;
	return;
}
ll query(int k,int l,int r,int x,int y)
{
	ll ret=0;
	pushdown(k,l,r);
	if(x<=l&&r<=y)	return sum[k]%mo;
	int mid = (l+r)/2;
	if(x<=mid)	ret=(ret%mo+query(k*2,l,mid,x,y)%mo)%mo;
	if(y>mid)	ret=(ret%mo+query(k*2+1,mid+1,r,x,y)%mo)%mo;
	return ret;
}
void add(int k,int l,int r,int x,int y,ll a)
{
	if(x<=l&&r<=y)		
	{
		sum[k]=(sum[k]%mo+(r-l+1)*a%mo)%mo;
		delA[k]=(delA[k]+a)%mo;
		return;
	}
	pushdown(k,l,r);
	ll mid = (l+r)/2;
	if(x<=mid)	add(k*2,l,mid,x,y,a);
	if(y>mid)	add(k*2+1,mid+1,r,x,y,a);
	sum[k]=(sum[k*2]%mo+sum[k*2+1]%mo)%mo;
}
void mul(int k,int l,int r,int x,int y,ll a)
{
	if(x<=l&&r<=y)		
	{
		sum[k]=sum[k]*a%mo;
		delM[k]=delM[k]*a%mo;
		delA[k]=delA[k]*a%mo;
		return;
	}
	pushdown(k,l,r);
	ll mid = (l+r)/2;
	if(x<=mid)	mul(k*2,l,mid,x,y,a);
	if(y>mid)	mul(k*2+1,mid+1,r,x,y,a);
	sum[k]=(sum[k*2]%mo+sum[k*2+1]%mo)%mo;
}
