bool simple(ll x){
	ll s=rs[x];
	if(s==0){
		if(q0.empty())
			return false;
		s=q0.front();
		rs[x]=s;
		q0.pop();
		prs(1,s,0);
		st[s].push_back(x);
	}
	else{
		rs[x]=0;
		q0.push(s);
		if(st[s].back()==x){
			prs(1,s,0);
			st[s].pop_back();
		}
		else{
			prs(1,sp,0);
			prs(2,sp,s);
			st[s].pop_front();
		}
	}
	return true;
}
void solve(){
	n=read();m=read();k=read();sp=n;
    while(!q0.empty())q0.pop();
