					st[s].push_back(p);
					for(int j=i+1;j<t;j++){
						if(y==a[j]){
							prs(1,sp,0);
						}
						else{
							simple(a[j]);
						}
					}
					prs(1,sp,0);
			    	prs(2,sp,s);
					st[s].pop_front();
					rs[x]=0;
					rs[p]=s;
				}
