#include<iostream>
#include<string>
using namespace std;
const int N = 105;
struct Grid {
	char a[N][N];
	int size;
	void read(int n) {
		size = n;
		for (int i = 0; i < size; i++) {
			for (int j = 0; j < size; j++) {
				cin >> a[i][j];
			}
		}
	}
	bool judge(Grid& b) const {
		for (int i = 0; i < size; i++) {
			for (int j = 0; j < size; j++) {
				if (a[i][j] != b.a[i][j]) {
					return false;
				}
			}
		}
		return true;
	}
	Grid rot90()const {
		Grid r;
		r.size = size;
		for (int i = 0; i < size; i++) {
			for (int j = 0; j < size; j++) {
				r.a[i][j] = a[size - 1 - j][i];
			}
		}
		return r;
	}
	Grid reflect()const {
		Grid r;
		r.size = size;
		for (int i = 0; i < size; i++) {
			for (int j = 0; j < size; j++) {
				r.a[i][j] = a[i][size - 1 - j];
			}
		}
		return r;
	}
};
int main() {
	int T;
	cin >> T;
	while (T--) {
		int n;
		cin >> n;
		Grid A;
		A.read(n);
		Grid B;
		B.read(n);
		int answer = 7;
		if (A.rot90().judge(B)) {
			answer = 1;
		}
		else if (A.rot90().rot90().judge(B)) {
			answer = 2;
		}
		else if (A.rot90().rot90().rot90().judge(B)) {
			answer = 3;
		}
		else if (A.reflect().judge(B)) {
			answer = 4;
		}
		else if(A.reflect().rot90().judge(B)|| 
			A.reflect().rot90().rot90().judge(B) || 
			A.reflect().rot90().rot90().rot90().judge(B)) {
			answer = 5;
		}
		else if(A.judge(B)){
			answer = 6;
		}
		cout << answer << endl;
	}
	return 0;
}
